package com.resolvenow.assignment;
import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AssignmentService { private static final Logger log=LoggerFactory.getLogger(AssignmentService.class); private final AssignmentRepository repository; private final NotificationClient notificationClient; public AssignmentService(AssignmentRepository repository,NotificationClient notificationClient){this.repository=repository;this.notificationClient=notificationClient;} public List<Assignment> all(){return repository.findAll();} public Assignment assign(Long complaintId,String recipient,String department,String agent){return repository.findByComplaintId(complaintId).orElseGet(() -> createAssignment(complaintId,recipient,department,agent));} private Assignment createAssignment(Long complaintId,String recipient,String department,String agent){Assignment saved; try{saved=repository.save(new Assignment(complaintId,department,agent));}catch(DataIntegrityViolationException exception){return repository.findByComplaintId(complaintId).orElseThrow(() -> exception);} try{notificationClient.notify(new NotificationClient.NotificationRequest(complaintId,recipient,"Complaint assigned to "+department+" / "+agent));}catch(RuntimeException exception){log.warn("Unable to notify customer for complaint {}",complaintId,exception);} return saved;} }
